<?php
require_once __DIR__ . '/config.php';
require_login();
if (user()['role'] !== 'user') { header('Location: admin/index.php'); exit; }
$q=db()->prepare('SELECT a.*,u.nama,u.email FROM applicants a JOIN users u ON u.id=a.user_id WHERE a.user_id=? LIMIT 1');
$q->execute([user()['id']]); $a=$q->fetch();
if (!$a) { flash('Data pendaftaran belum tersedia.'); header('Location: dashboard.php'); exit; }
$allowed=$a['status'] !== 'Biodata belum lengkap' && !empty($a['prodi']);
$attemptCheck=db()->prepare('SELECT id FROM exam_attempts WHERE applicant_id=? LIMIT 1');
$attemptCheck->execute([$a['id']]);
$hasAttempt=(bool)$attemptCheck->fetchColumn();
?>
